import {readFile,writeFile} from 'node:fs/promises';
import {documentedRelationships,relationshipRules,ruleReferences,verbs,serviceExclusions} from '../catalog/relationship-rules.js';
const services=JSON.parse(await readFile(new URL('../catalog/services.json',import.meta.url),'utf8'));
const names=new Map(services.map(s=>[s.id,s.name]));
const cell=value=>String(value).replaceAll('|','\\|').replaceAll('\n',' ');
const text=[
 '# Documented relationship catalog',
 '',
 'Generated by `node catalog-sources/document-relationships.mjs` from `catalog/relationship-rules.js`.',
 '',
 `This curated catalog contains ${documentedRelationships.length} documented relationships across ${relationshipRules.length} directed service pairs. Its ${verbs.length} labels are the unique union of those relationships. It is not an exhaustive inventory of AWS integrations.`,
 '',
 'A label consolidates the operations listed beneath it. Direction represents the stated operation or configuration: a Lambda queue consumer reads from SQS; SQS handled by Lambda describes processing through a Lambda event source mapping; an SQS queue subscribes to an SNS topic, or the SNS topic is subscribed by the SQS queue. These two labels describe the same subscription in opposite directions. SNS sends to SQS describes message delivery over that subscription. A subscription arrow describes configuration, not an API request initiated by SQS. DNS routing does not proxy application traffic.',
 '',
 'Unknown pairs have no selectable relationship until evidence is added. Missing coverage is not proof that an integration is impossible. Runtime validation checks catalog membership; it does not inspect IAM, network reachability, regions, API types, or resource configuration. Each claim records relevant scope and source evidence for review.',
 '',
 'Saved and imported edges are preserved and marked for documentation review when unsupported. They are not part of the selectable vocabulary and are never automatically relabeled or reversed.',
 '',
 '## Vocabulary',
 '',
 verbs.map(v=>`\`${v}\``).join(', '),
 '',
 '## Supported relationships',
 '',
 '| Source | Relationship | Target | Documented operation | Scope | Reviewed | Evidence |',
 '| --- | --- | --- | --- | --- | --- | --- |',
 ...documentedRelationships.map(row=>`| ${cell(names.get(row.source))} | ${row.verb} | ${cell(names.get(row.target))} | ${cell(row.operation)} | ${cell(row.condition)} | ${row.reviewed} | ${row.references.map(ref=>`[${ref}](${ruleReferences[ref].url})`).join(', ')} |`),
 '',
 '## Explained exclusions',
 '',
 'These icons remain available for diagrams, but have no selectable relationships. Imported connections are preserved for review. Retirement dates are evaluated as of the recorded review date.',
 '',
 '| Catalog entry | Reason | Reviewed | Evidence |',
 '| --- | --- | --- | --- |',
 ...serviceExclusions.map(entry=>`| ${cell(names.get(entry.id))} | ${cell(entry.reason)} | ${entry.reviewed} | ${entry.references.map(ref=>`[Source](${ref.url})`).join(', ')} |`),
 '',
 '## Source evidence',
 '',
 'Review dates are recorded per claim. Summaries below paraphrase primary AWS and product documentation. Artist-tool scripting APIs describe local plugin workflows, not AWS service endpoints. Lambda SDK relationships combine the documented ability to call service APIs from function code with the specific destination operation; they do not imply an automatic service-to-service integration.',
 '',
 ...Object.entries(ruleReferences).map(([id,ref])=>`- [${id}](${ref.url}): ${ref.summary}`),
 ''
].join('\n');
await writeFile(new URL('../docs/relationships.md',import.meta.url),text);
